def _ledger(data, sequence_first, tax_discounted, refund=True):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if tax_discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refund and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {r["version"]: r for r in versions}
            for name, versions in packages.items()}
    choices = [[None] + sorted(rows[name]) for name in names]
    best_vector = None
    best = None

    def check(selection):
        installed = {name: ver for name, ver in zip(names, selection) if ver is not None}
        for name, ver in installed.items():
            if ver in blocked.get(name, []) or (name in pins and pins[name] != ver):
                return None
        for name, (low, high) in roots.items():
            if name not in installed or not low <= installed[name] <= high:
                return None

        edges = {name: [] for name in installed}
        constraints = {}
        for name, ver in installed.items():
            for dep in rows[name][ver].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                edges[name].append(target)
                constraints.setdefault(target, []).append((dep["min"], dep["max"]))
                if target not in installed:
                    return None
                if not dep["min"] <= installed[target] <= dep["max"]:
                    return None
        for name, ranges in constraints.items():
            ver = installed[name]
            if any(not low <= ver <= high for low, high in ranges):
                return None

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True
        if any(not visit(name) for name in installed):
            return None

        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            stack.extend(edges[name])
        if reached != set(installed):
            return None
        return installed

    def search(i, selection):
        nonlocal best_vector, best
        if i == len(names):
            installed = check(selection)
            if installed is None:
                return
            vector = tuple(-1 if v is None else v for v in selection)
            if best_vector is None or vector < best_vector:
                best_vector, best = vector, installed
            return
        for version in choices[i]:
            search(i + 1, selection + [version])

    search(0, [])
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _schedule(data):
    from itertools import combinations
    jobs = data["jobs"]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    blocked = set(data.get("blocked", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids or ids & blocked:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(a["end"] > b["start"] for a, b in zip(ordered, ordered[1:])):
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _route(data):
    import heapq
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start_state = (start_node, data["coupons"], start_mask)
    dist = {start_state: data["start"]}
    queue = [(data["start"], start_node, data["coupons"], start_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if dist.get(state) != time:
            continue
        if node == data["target"] and remaining == 0 and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_remaining, next_mask)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


